head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setColumnIoFormat]<br/>Body Column 정보를 사용하여 특정 Column 의 ioFormat 속성을 설정합니다.",
    "validation" : [
        "columnInfo(필수) 파라미터는 Row 가 MultiLine 이어도 모든 Column 은 고유의 인덱스값을 갖습니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Body Row MultiLine 구성)
//  - gBody 에 <w2:row> 2개 -> 한 데이터 Row 가 2 Line 으로 표시
//  - 1줄 = col1(인덱스0:text) / col2(인덱스1:date, dataType="date")
//  - 2줄 = col3(인덱스2:text) / col4(인덱스3:date, dataType="date")
//  - Row 가 MultiLine 이어도 col1~col4 는 각각 고유 인덱스(0~3) 를 가짐
//  - setColumnIoFormat 은 dataType="date" 이고 inputType 이 "custom" 이 아닌 컬럼에서만 동작
//    -> 고유 인덱스 1, 3 (date 컬럼) 으로 호출 시 해당 컬럼에만 ioFormat/displayFormat 설정됨
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // MultiLine 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Body 가 MultiLine(2줄). 한 데이터 Row 가 2줄에 걸쳐 표시됨. 1줄 col1(0:text)/col2(1:date, dataType=date, 초기 yyyy.MM.dd), 2줄 col3(2:text)/col4(3:date, dataType=date, 초기 yyyy.MM.dd) 고유 인덱스. setColumnIoFormat 은 date 컬럼에서만 동작하므로 대상은 고유 인덱스 1, 3. 데이터 Row 3개.\n[절차] columnInfo(0~3) 선택 -> (setColumnIoFormat 실행). date 컬럼(1,3) 셀 더블클릭 편집 후 포커스아웃하면 편집값(ioFormat)·표시값(displayFormat)이 자동 출력됨.\n[확인] MultiLine 이어도 col1~col4 는 고유 인덱스(0~3)로 각각 지목됨. date 컬럼(1,3) 호출 시 해당 컬럼만 ioFormat=ddMMyyyy / displayFormat=yyyy-MM-dd 설정되어 표시값이 yyyy-MM-dd 로 변경(다른 컬럼 영향 없음). getColumnID(인덱스) 매핑도 출력."', '', 'label1');

    // dataList 생성 + 초기값 바인딩
    //  - col1:text / col2:date(yyyyMMdd) / col3:text / col4:date(yyyyMMdd)
    let strData = '';
    strData += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strData += '<w2:columnInfo>';
    strData += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strData += '<w2:column id="col2" name="col2" dataType="date"></w2:column>';
    strData += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strData += '<w2:column id="col4" name="col4" dataType="date"></w2:column>';
    strData += '</w2:columnInfo>';
    strData += '<w2:data use="true"></w2:data>';
    strData += '</w2:dataList>';
    $p.data.create(strData);
    dlt_bind.setJSON([
        { "col1": "서울 강남점", "col2": "20250115", "col3": "정상영업", "col4": "20250701" },
        { "col1": "부산 해운대점", "col2": "20250220", "col3": "정상영업", "col4": "20250815" },
        { "col1": "대구 수성점", "col2": "20250312", "col3": "리모델링", "col4": "20250920" }
    ]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // target 생성 (Body Row MultiLine : gBody 에 <w2:row> 2개)
    //  - 1줄 : col1(0:text) / col2(1:date)
    //  - 2줄 : col3(2:text) / col4(3:date)
    //  - Row 가 MultiLine 이어도 모든 Column 은 고유 인덱스(0~3)
    //  - col2/col4 는 dataType="date" 초기 displayFormat=yyyy.MM.dd -> setColumnIoFormat 적용 시 yyyy-MM-dd 로 변화
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' checkAllType="false" dataList="data:dlt_bind" id="" style="width:560px;height:340px;" editable="true" ev:onbeforeedit="scwin.target1_onbeforeedit" ev:onafteredit="scwin.target1_onafteredit">';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol1" value="지점명(text)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol2" value="개설일(date)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="hrow2">';
    strTarget += '<w2:column width="280" inputType="text" id="hcol3" value="운영상태(text)"></w2:column>';
    strTarget += '<w2:column width="*" inputType="text" id="hcol4" value="점검일(date)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    // index 0 : col1 (text, 1줄 첫 컬럼, 고유 인덱스 0)
    strTarget += '<w2:column width="280" inputType="text" dataType="text" id="col1" dataList="col1"></w2:column>';
    // index 1 : col2 (date, 1줄 마지막, 고유 인덱스 1. 초기 displayFormat=yyyy.MM.dd -> 적용 시 yyyy-MM-dd 로 변화)
    strTarget += '<w2:column width="*" inputType="text" dataType="date" displayFormat="yyyy.MM.dd" id="col2" dataList="col2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '<w2:row style="" id="brow2">';
    // index 2 : col3 (text, 2줄 첫 컬럼, 고유 인덱스 2)
    strTarget += '<w2:column width="280" inputType="text" dataType="text" id="col3" dataList="col3"></w2:column>';
    // index 3 : col4 (date, 2줄 마지막, 고유 인덱스 3. 초기 displayFormat=yyyy.MM.dd -> 적용 시 yyyy-MM-dd 로 변화)
    strTarget += '<w2:column width="*" inputType="text" dataType="date" displayFormat="yyyy.MM.dd" id="col4" dataList="col4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);
}



// [실행] setColumnIoFormat : 선택한 컬럼(고유 누적 인덱스) 에만 ioFormat / displayFormat 속성을 설정
//  - MultiLine(2줄) 이어도 col1~col4 는 고유 인덱스(0~3) 로 정확히 지목됨
//  - date 컬럼(고유 인덱스 1, 3) 에서만 동작. text 컬럼(0, 2) 은 미동작
scwin.btn_setColumnIoFormat_onclick = function () {
    let columnInfo = Number(par_columnInfo.getValue());
    let colID = target1.getColumnID(columnInfo);   // MultiLine Row 에서도 col1~col4 는 고유 인덱스(0~3)

    // 고유 인덱스로 해당 컬럼에만 ioFormat / displayFormat 설정
    target1.setColumnIoFormat(columnInfo, "ddMMyyyy", "yyyy-MM-dd");

    let opt = target1.getCellInfo(columnInfo).options;
    let arr = scwin.collectColText(columnInfo);

    let msg = "setColumnIoFormat(" + columnInfo + ", 'ddMMyyyy', 'yyyy-MM-dd') [인덱스 " + columnInfo + " -> getColumnID:" + colID + "]";
    msg += "\n[속성] ioFormat='" + opt.ioFormat + "' / displayFormat='" + opt.displayFormat + "'";
    msg += "\n[표시값] " + arr.join(', ');
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
}

// 해당 Column 의 모든 Row 화면 표시값(td.textContent) 수집
scwin.collectColText = function (colIndex) {
    let cnt = dlt_bind.getRowCount();
    let arr = [];
    for (let r = 0; r < cnt; r++) {
        let td = document.querySelector("td[id*='target1_cell_" + r + "_" + colIndex + "']");
        arr.push(td ? td.textContent.trim() : '');
    }
    return arr;
}

// [이벤트] 셀을 직접 편집 -> 포커스 아웃(onafteredit) 하는 실제 인터랙션마다 편집값(ioFormat)/표시값(displayFormat) 자동 출력
//  - date 컬럼(고유 인덱스 1, 3) 만 ioFormat 적용. value = 편집 입력창 값(ioFormat), 포커스아웃 후 Cell 표시값 = displayFormat
scwin.target1_onbeforeedit = function (row, col, value) {
    scwin._editIoValue = value;
};
scwin.target1_onafteredit = function (row, col, value) {
    let colID = target1.getColumnID(col);
    let td = document.querySelector("td[id*='target1_cell_" + row + "_" + col + "']");
    let dispVal = td ? td.textContent.trim() : '';
    let msg = "편집->포커스아웃 [" + colID + "] (" + row + "," + col + ")";
    msg += "\n[편집값(ioFormat)] " + value;
    msg += "\n[표시값(displayFormat)] " + dispVal;
    wf_body_bottom.getObj("scwin").setReturnValue(msg);
};
